public class QuorumWriteCoordinator {
    private final List<StorageNode> replicas;
    private final int writeQuorum;

    public QuorumWriteCoordinator(List<StorageNode> replicas, int writeQuorum) {
        this.replicas = replicas;
        this.writeQuorum = writeQuorum;
    }

    public CompletableFuture<Boolean> write(String key, byte[] value) {
        List<CompletableFuture<Boolean>> futures = replicas.stream()
            .map(node -> CompletableFuture.supplyAsync(() -> node.put(key, value)))
            .collect(Collectors.toList());

        return CompletableFuture.allOf(futures.toArray(new CompletableFuture[0]))
            .thenApply(v -> {
                long successfulWrites = futures.stream()
                    .filter(f -> f.join())
                    .count();
                return successfulWrites >= writeQuorum;
            });
    }
}
